import { existsSync } from 'node:fs';

import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

import {
  CHAT_FILE,
  IMPORT_PATH,
  PII_CHAT,
  enableWhatsAppImport,
} from './whatsapp-import-helpers.ts';

// `@visual` baselines for the WhatsApp import (#527): the chat-type step and the preview with
// held-back messages. Baselines are only ever generated by the e2e workflow's `update_snapshots`
// dispatch in the pinned Playwright image (see e2e/README.md).
for (const shot of ['chat-type', 'preview'] as const) {
  test(`whatsapp-import ${shot}`, { tag: '@visual' }, async ({ page, asUser, db }, testInfo) => {
    const baseline = testInfo.snapshotPath(`whatsapp-import-${shot}.png`, { kind: 'screenshot' });
    test.skip(
      testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
      'no baseline yet: dispatch the e2e workflow with update_snapshots',
    );
    await enableWhatsAppImport(db.name);
    await asUser('owner', { path: IMPORT_PATH });
    await shellReady(page);
    if (shot === 'preview') {
      await page.getByRole('radio', { name: /Internal/ }).check();
      await page.getByRole('button', { name: 'Continue' }).click();
      await page.locator('input[type="file"]').setInputFiles({
        name: CHAT_FILE,
        mimeType: 'text/plain',
        buffer: Buffer.from(PII_CHAT),
      });
      await expect(page.getByText('2 messages selected of 4')).toBeVisible();
    }
    await expect(page).toHaveScreenshot(`whatsapp-import-${shot}.png`, { fullPage: true });
  });
}
